import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.Cdp8-jB6.js";const g=JSON.parse('{"title":"Spacecraft anatomy art — generation runbook (#367)","description":"","frontmatter":{},"headers":[],"relativePath":"anatomy-art-runbook.md","filePath":"anatomy-art-runbook.md"}'),n={name:"anatomy-art-runbook.md"};function o(r,e,l,d,c,h){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="spacecraft-anatomy-art-—-generation-runbook-367" tabindex="-1">Spacecraft anatomy art — generation runbook (#367) <a class="header-anchor" href="#spacecraft-anatomy-art-—-generation-runbook-367" aria-label="Permalink to &quot;Spacecraft anatomy art — generation runbook (#367)&quot;">​</a></h1><p>How to generate the remaining spacecraft anatomy illustrations <strong>in the same style</strong> as the 72 already shipped, and wire them in end-to-end.</p><p>The art is AI-generated (Higgsfield <code>nano_banana_pro</code>) editorial cutaways. The whole point of this doc is <strong>style consistency</strong> — a new batch must look like it came from the same hand as the existing set.</p><hr><h2 id="_0-the-golden-rules-read-first-—-this-is-how-we-avoid-drift" tabindex="-1">0. The golden rules (read first — this is how we avoid drift) <a class="header-anchor" href="#_0-the-golden-rules-read-first-—-this-is-how-we-avoid-drift" aria-label="Permalink to &quot;0. The golden rules (read first — this is how we avoid drift)&quot;">​</a></h2><p>Batches look different when the recipe drifts. To prevent that:</p><ol><li><strong>Copy the prompt recipe VERBATIM.</strong> Only swap the bracketed parts (<code>[CRAFT]</code>, <code>[KEY PARTS]</code>, <code>[AGENCY]</code>). Do <strong>not</strong> paraphrase the style clauses (&quot;watercolor and ink-wash on faint graph paper …&quot;). Those clauses ARE the style.</li><li><strong>Never change the model.</strong> Always <code>nano_banana_pro</code>.</li><li><strong>Never change aspect ratio per style:</strong> watercolor = <code>3:2</code>, pencil = <code>2:3</code>.</li><li><strong>Strongest guard — pass a reference image.</strong> Hand the model one of the existing illustrations as a style reference (see §3). This locks the look far more tightly than text alone. Use a watercolor reference for watercolor craft, a pencil reference for launchers.</li><li><strong>QC every batch against the existing set</strong> — render a contact sheet (<code>build-anatomy-webp</code> already lists ids) and eyeball it next to a few of the shipped ones before committing. Regenerate any that drift.</li></ol><hr><h2 id="_1-style-assignment" tabindex="-1">1. Style assignment <a class="header-anchor" href="#_1-style-assignment" aria-label="Permalink to &quot;1. Style assignment&quot;">​</a></h2><ul><li><strong>Launchers (rockets) → PENCIL sketch</strong> (<code>2:3</code>, white sketchbook paper).</li><li><strong>Everything else (crewed, cargo, orbiters, landers, rovers, observatories, stations) → WATERCOLOR cutaway</strong> (<code>3:2</code>, graph paper).</li></ul><hr><h2 id="_2-the-two-recipes-verbatim-templates" tabindex="-1">2. The two recipes (verbatim templates) <a class="header-anchor" href="#_2-the-two-recipes-verbatim-templates" aria-label="Permalink to &quot;2. The two recipes (verbatim templates)&quot;">​</a></h2><h3 id="watercolor-payload-craft-—-aspect-3-2" tabindex="-1">Watercolor (payload craft) — aspect <code>3:2</code> <a class="header-anchor" href="#watercolor-payload-craft-—-aspect-3-2" aria-label="Permalink to &quot;Watercolor (payload craft) — aspect \`3:2\`&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Technical cutaway illustration of [CRAFT], watercolor and ink-wash on faint</span></span>
<span class="line"><span>graph paper, exposed internal structure — [KEY PARTS]. Handwritten engineering</span></span>
<span class="line"><span>annotations, dimension lines, faint physics equations in the margins,</span></span>
<span class="line"><span>ink-splatter wash clouds, warm muted metallic palette, vintage scientific</span></span>
<span class="line"><span>sketchbook / editorial infographic aesthetic. [AGENCY] markings.</span></span></code></pre></div><p>Palette hints you may append where apt: <code>rusty</code> for Mars craft, <code>with solar gold</code> for sun-facing, <code>ochre-metallic</code> for Venus.</p><h3 id="pencil-launchers-—-aspect-2-3" tabindex="-1">Pencil (launchers) — aspect <code>2:3</code> <a class="header-anchor" href="#pencil-launchers-—-aspect-2-3" aria-label="Permalink to &quot;Pencil (launchers) — aspect \`2:3\`&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Loose hand-drawn pencil sketch of [CRAFT], vertical, on white sketchbook paper.</span></span>
<span class="line"><span>Graphite shading, expressive cross-hatching, rough artistic linework,</span></span>
<span class="line"><span>monochrome grey, engineering concept sketch. [KEY PARTS/STAGES]. A few sketchy</span></span>
<span class="line"><span>handwritten labels.</span></span></code></pre></div><p><code>[KEY PARTS]</code> = the craft&#39;s real structure (bus, antenna, solar config, engines, booms…). Accuracy matters — research the actual layout per craft.</p><hr><h2 id="_3-generating-higgsfield-mcp" tabindex="-1">3. Generating (Higgsfield MCP) <a class="header-anchor" href="#_3-generating-higgsfield-mcp" aria-label="Permalink to &quot;3. Generating (Higgsfield MCP)&quot;">​</a></h2><p>One call per craft (<code>mcp__claude_ai_Higgsfield__generate_image</code>):</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;model&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;nano_banana_pro&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;params&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;prompt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;recipe&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;aspect_ratio&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;3:2&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;count&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><p>Up to <strong>8 concurrent</strong> on the PLUS plan — fire a wave of 8, then poll (<code>job_status</code> with <code>sync:true</code>) to get the result URLs. Each image = <strong>2 credits</strong>.</p><h3 id="reference-image-anti-drift-recommended" tabindex="-1">Reference-image anti-drift (recommended) <a class="header-anchor" href="#reference-image-anti-drift-recommended" aria-label="Permalink to &quot;Reference-image anti-drift (recommended)&quot;">​</a></h3><p>To pin the style, attach an existing illustration as a reference:</p><ol><li><code>media_import_url</code> (or <code>media_upload</code>) one of the shipped images, e.g. the raw URL of <code>static/images/anatomy/voyager-2</code> (a clean watercolor) — get back a <code>media_id</code>.</li><li>Pass it in <code>params.medias: [{ &quot;value&quot;: &quot;&lt;media_id&gt;&quot;, &quot;role&quot;: &quot;&lt;style/ref role from models_explore&gt;&quot; }]</code>. Check <code>models_explore</code> for the exact role name nano_banana_pro expects for a style/reference image.</li></ol><p>Keep one watercolor ref + one pencil ref handy and reuse them across the batch.</p><hr><h2 id="_4-download-→-resize-→-wire-per-wave" tabindex="-1">4. Download → resize → wire (per wave) <a class="header-anchor" href="#_4-download-→-resize-→-wire-per-wave" aria-label="Permalink to &quot;4. Download → resize → wire (per wave)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Download each result PNG into the committed originals dir, named by id:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> original-assets/anatomy/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.png</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&lt;rawUrl&gt;&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Resize to webp + regenerate the id manifest (anatomy-ids.json):</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build-anatomy-webp.mjs</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Regenerate the colophon bill-of-materials:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build-original-work.mjs</span></span></code></pre></div><p>That&#39;s it — the manifest is <strong>auto-derived</strong>:</p><ul><li><code>src/lib/spacecraft-diagrams.ts</code> builds <code>SPACECRAFT_ANATOMY_IMG</code> from <code>anatomy-ids.json</code> (no hand-edit). The fleet DETAIL tab + station panels read it. Underscore station-visitor ids alias to the kebab webp via <code>ANATOMY_ALIAS</code> — add an entry there only for a NEW underscore/kebab split.</li><li><code>/colophon</code> &quot;Spacecraft cutaways&quot; section + the consistency test pick the new ids up automatically.</li></ul><h3 id="verify-commit" tabindex="-1">Verify + commit <a class="header-anchor" href="#verify-commit" aria-label="Permalink to &quot;Verify + commit&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/lib/spacecraft-diagrams.test.ts</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # ids &lt;-&gt; webp in sync</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i18n:compile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> svelte-check</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tsconfig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./tsconfig.json</span></span></code></pre></div><p>Commit <strong>only</strong> the anatomy files (parallel agents work this repo — never <code>git add -A</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> original-assets/anatomy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> static/images/anatomy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/lib/anatomy-ids.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        static/data/original-work.json</span></span></code></pre></div><p>Full-res PNGs live in <code>original-assets/anatomy/</code> (committed backup); the app serves the ~130 KB webp from <code>static/images/anatomy/</code>.</p><hr><h2 id="_5-remaining-craft" tabindex="-1">5. Remaining craft <a class="header-anchor" href="#_5-remaining-craft" aria-label="Permalink to &quot;5. Remaining craft&quot;">​</a></h2><p>Style in (): P = pencil, W = watercolor. Marko&#39;s call was <strong>notable first, obscure long-tail last</strong>.</p><p><strong>✅ The 72 notable craft are DONE</strong> (generated 2026-06-22, all on disk + wired). The full notable set — 53 watercolor + 19 pencil launchers — shipped in one batch using the locked recipe; ids and prompts are preserved verbatim in <code>/tmp/anatomy-prompts.mjs</code> (regenerate any time with <code>node</code>). The <code>[tail]</code> craft below are all that&#39;s left, and were deliberately deferred as obscure.</p><blockquote><p>Don&#39;t re-generate the 72 — <code>node scripts/build-anatomy-webp.mjs</code> + the missing-check (§4) will show they&#39;re already present. Only the tail is open.</p></blockquote><p><strong><code>[tail]</code> launcher (P):</strong> atlas-lv-3b, atlas-slv-3d, proton-k, r-7-vostok, soyuz-fg, soyuz-u, titan-ii-glv, vostok-k, voskhod-11a57</p><p><strong><code>[tail]</code> orbiter (W):</strong> change-1, change-2, clementine, giotto, phobos-2, vega-1, vega-2, luna10, viking1-orbiter, mars2-orbiter, mars3-orbiter, lunar-orbiter-1..5</p><p><strong><code>[tail]</code> lander (W):</strong> mars-2, mars-polar-lander, vikram-cy2, luna24, change6, viking2-lander, mars6, beagle2</p><p><strong><code>[tail]</code> station (W):</strong> salyut-2, salyut-3, salyut-4, salyut-5</p><p><strong><code>[tail]</code> crewed-spacecraft (W):</strong> the named Shuttle orbiters (atlantis/columbia/discovery/endeavour/challenger/enterprise — visually identical to the existing space-shuttle-orbiter, skip or do one), buran-ok-gli, soyuz-7k-ok, soyuz-t, soyuz-tm, voskhod, apollo-csm-block-i</p><p><strong><code>[tail]</code> cargo-spacecraft (W):</strong> cygnus-standard (alias to cygnus-enhanced instead), progress-7k-tg</p><hr><h2 id="_6-where-everything-lives" tabindex="-1">6. Where everything lives <a class="header-anchor" href="#_6-where-everything-lives" aria-label="Permalink to &quot;6. Where everything lives&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Thing</th><th>Path</th></tr></thead><tbody><tr><td>Generated originals (committed backup)</td><td><code>original-assets/anatomy/*.png</code></td></tr><tr><td>Served display images</td><td><code>static/images/anatomy/*.webp</code></td></tr><tr><td>Id manifest (auto-derived)</td><td><code>src/lib/anatomy-ids.json</code></td></tr><tr><td>Resolver + visitor aliases</td><td><code>src/lib/spacecraft-diagrams.ts</code></td></tr><tr><td>Resize + ids script</td><td><code>scripts/build-anatomy-webp.mjs</code></td></tr><tr><td>Colophon bill-of-materials</td><td><code>scripts/build-original-work.mjs</code> → <code>static/data/original-work.json</code></td></tr><tr><td>Consistency test</td><td><code>src/lib/spacecraft-diagrams.test.ts</code></td></tr><tr><td>Fleet DETAIL tab render</td><td><code>src/lib/components/FleetEntryPanel.svelte</code></td></tr><tr><td>Colophon showcase</td><td><code>src/routes/colophon/+page.svelte</code></td></tr></tbody></table>`,51)])])}const k=a(n,[["render",o]]);export{g as __pageData,k as default};
